Please note that this is a simplified model and does not take into account many real-world factors that could affect the pendulum's motion, such as air resistance and the non-uniformity of gravity.

```
// The pendulum object
let pendulum = {
  angle: 0, // initial angle
  angularVelocity: 0, // initial angular velocity
  gravity: 9.81, // gravity constant
  length: 100, // pendulum length
  mass: 1, // pendulum mass
  canvas: null, // reference to the canvas element
  ctx: null // reference to the canvas context
};

// Initialize the pendulum
function init() {
  pendulum.canvas = document.getElementById("pendulumCanvas");
  pendulum.ctx = pendulum.canvas.getContext("2d");
  pendulum.ctx.font = "16px Arial";
  pendulum.ctx.textAlign = "center";
  pendulum.ctx.textBaseline = "middle";
  pendulum.ctx.clearRect(0, 0, pendulum.canvas.width, pendulum.canvas.height);
  pendulum.angle = parseFloat(prompt("Enter the initial angle (in degrees):"));
  pendulum.angularVelocity = 0;
}

// Update the pendulum state
function update(dT) {
  let F = -pendulum.gravity * pendulum.mass * Math.sin(Math.PI / 180 * pendulum.angle);
  let torque = F * pendulum.length;
  pendulum.angularVelocity += torque / (pendulum.mass * pendulum.length ** 2);
  pendulum.angle += pendulum.angularVelocity * dT;
}

// Draw the pendulum
function draw() {
  pendulum.ctx.clearRect(0, 0, pendulum.canvas.width, pendulum.canvas.height);
  let x = pendulum.canvas.width / 2 + pendulum.length * Math.sin(Math.PI / 180 * pendulum.angle);
  let y = pendulum.canvas.height / 2 - pendulum.length * Math.cos(Math.PI / 180 * pendulum.angle);
  pendulum.ctx.beginPath();
  pendulum.ctx.arc(x, y, 5, 0, 2 * Math.PI);
  pendulum.ctx.fillStyle = "blue";
  pendulum.ctx.fill();
  pendulum.ctx.fillStyle = "black";
  pendulum.ctx.textAlign = "center";
  pendulum.ctx.textBaseline = "middle";
  pendulum.ctx.fillText(parseInt(pendulum.angle) + "°", x, y);
}

// Animate the pendulum
function animate(time, frame) {
  let dT = time / 1000; // convert time to seconds
  update(dT);
  draw();
  if (frame) {
    requestAnimationFrame(() => animate(requestAnimationFrameAnimationFrame=>animate(requestAnimationFrameAnimationFrame, 1)))); // recursive call
  }
}

// Start the pendulum animation
function startAnimation() {
  animate(requestAnimationFrame, 1);
}

// Handle the release button click event
document.getElementById("releaseButton").addEventListener("click", startAnimation);

init();
```

