	log.Printf("Found %d snapshots", len(res.Snapshots))
	snapshots := make([]*ec2.Snapshot, len(res.Snapshots))
	for i, s := range res.Snapshots {
		snapshots[i] = s
	}
	sort.Slice(snapshots, func(i, j int) bool {
		return *snapshots[i].StartTime < *snapshots[j].StartTime
	})

	// Delete snapshots that exceed the retention policy
	for _, s := range snapshots {
		tag, exists := findTag(s.Tags, "backup-type")
		if !exists {
			log.Printf("snapshot %s has no backup-type tag", *s.SnapshotId)
			continue
		}

		backupType, err := strconv.ParseString(*tag, "", 10)
		if err != nil {
			log.Printf("invalid tag value %s for snapshot %s", *tag, *s.SnapshotId)
			continue
		}

		switch backupType {
		case "monthly":
			if len(snapshots) <= 14 {
				continue
			}
			snapshots = snapshots[:14]
		case "daily":
			if len(snapshots) <= 10 {
				continue
			}
			snapshots = snapshots[:10]
		case "weekly":
			if len(snapshots) <= 4 {
				continue
			}
			snapshots = snapshots[:4]
		case "yearly":
			// only keep the most recent snapshot
			continue
		default:
			log.Printf("unknown backup-type %s for snapshot %s", *tag, *s.SnapshotId)
			continue
		}

		err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
			SnapshotId: aws.String(*s.SnapshotId),
		})
		if err != nil {
			log.Printf("failed to delete snapshot %s: %s", *s.SnapshotId, err)
		} else {
			log.Printf("deleted snapshot %s", *s.SnapshotId)
		}
	}

	return nil, nil
}

func findTag(tags []*ec2.Tag, key string) (*string, bool) {
	for _, tag := range tags {
		if *tag.Key == key {
			return tag.Value, true
		}
	}
	return nil, false
}

